SourceCode.Declaration:
/// <summary>
/// Marks a method on a subclass of <c>OLK_EnvironmentDataSetupExecuteCode</c> as a code job and describes it.
/// </summary>
public class OLK_EnvironmentDataSetupAttribute extends SysAttribute
{
    FreeTxt description;
}

Method.Source:
public FreeTxt parmDescription(FreeTxt _description = description)
{
    description = _description;

    return description;
}
